window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6266e54630fa8845"]={"versions": [{"id": "FIG-6266e54630fa8845", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Paketdiagramm (Package Diagram) des AUTOSAR-Metamodells auf MOF-Ebene M2 (Meta-Object Facility).\n</li><li><strong>Technischer Zweck:</strong> Definition der Modularisierung, Kapselung und statischen Abhängigkeitsstruktur der AUTOSAR-Templates für Classic Platform (CP) und Teile der Adaptive Platform (AP) im Release R23-11.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet das normative Schema (Basis für die Generierung des <code>AUTOSAR_*.xsd</code>-XML-Schemas) für alle AUTOSAR-Autorendateien (ARXML).\n</li><li>Strukturierung der Domänen in spezifische Templates (System, SWC, BSW, ECU-C, HW-Ressourcen, Diagnose) zur Trennung von Systemdesign-, Integrations- und Konfigurations-Phasen.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Struktur- und Basis-Pakete</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarTopLevelStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Beherbergt die singuläre Wurzel-Metaklasse <code>AUTOSAR</code> des gesamten ARXML-Instanzmodells.\n</li><li>Aggregiert generisch alle Metaklassen über hierarchisch geschachtelte <code>ARPackage</code>-Elemente aus den Template-Paketen.\n</li></ul>\n</li><li><strong><code>CommonStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Plattformweite Basis-Metaklassen: Identifizierbarkeit (<code>Identifiable</code>, <code>Referrable</code>), primitive Datentypen, physische Einheiten/Dimensionen (<code>Unit</code>, <code>PhysicalDimension</code>), Formeln (<code>CompuMethod</code>) sowie Metadaten/Rechteverwaltung (<code>AdminData</code>).\n</li></ul>\n</li><li><strong><code>GenericStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Orthogonale Modellierungsprimitive: Typ-Instanz-Muster, generische Assoziationen, Primitive-Typ-Konzepte. Alle Top-Level-Pakete aggregieren Metaklassen aus diesem Paket (dokumentiert per Annotation).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Funktionale Template-Pakete (Classic Platform Core)</h5>\n<ul class=\"fig-list\"><li><strong><code>SWComponentTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Modellierung des Virtual Functional Bus (VFB) und der Software-Architektur: Software-Komponenten-Typen (<code>AtomicSwComponentType</code>, <code>CompositionSwComponentType</code>), Ports (<code>RPortPrototype</code>, <code>PPortPrototype</code>), Interfaces (<code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>) sowie internes Verhalten (<code>SwcInternalBehavior</code>, <code>RunnableEntity</code>).\n</li></ul>\n</li><li><strong><code>SystemTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Systemweit integrierte Beschreibung: Bus-Topologie (<code>CanCluster</code>, <code>LinCluster</code>, <code>EthernetCluster</code>), Kommunikationsmatrix (<code>Frame</code>, <code>I-PDU</code>, <code>ISignal</code>), System-Signals, ECU-Instanzen (<code>EcuInstance</code>) sowie Mappings (<code>SwcToEcuMapping</code>, <code>SystemSignalISignalMapping</code>).\n</li></ul>\n</li><li><strong><code>EcuResourceTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Hardware-Ressourcen der Steuergeräte: Mikrocontroller-Architektur, CPU-Cores, On-Chip- und Off-Chip-Peripherie, Pins und Speicherabbilder (<code>HwDescriptionEntity</code>).\n</li></ul>\n</li><li><strong><code>BswModuleTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Formale Beschreibung von BSW-Modulen und Treibern (MCAL, HAL, Service-Layer): <code>BswModuleDescription</code>, <code>BswInternalBehavior</code>, BSW-Schedulables (<code>BswSchedulableEntity</code>), Speicherzuordnungen und OS-Task-Anbindungen.\n</li></ul>\n</li><li><strong><code>ECUCParameterDefTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Metamodell für Modul-Parameter-Definitionen: Definition von Parametern, Containern und Multiplizitäten (<code>EcucModuleDef</code>, <code>EcucParamConfContainerDef</code>) für BSW-Stacks und RTE.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Konkrete ECU-Konfigurationswerte (<code>EcucValueCollection</code>, <code>EcucModuleConfigurationValues</code>), validiert gegen die zugehörigen <code>ECUCParameterDefTemplates</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Domänenübergreifende &amp; Erweiterungs-Pakete</h5>\n<ul class=\"fig-list\"><li><strong><code>AdaptivePlatform</code>:</strong> Metamodellelemente für serviceorientierte Architekturen (SOA), Adaptive Application Manifeste und Deployment.\n</li><li><strong><code>DiagnosticExtract</code>:</strong> DEXT-Diagnosespezifikation (DTCs, Diagnostic Services, Dcm/Dem-Mappings).\n</li><li><strong><code>AbstractPlatform</code>:</strong> Plattformunabhängige Abstraktionsschicht zur Harmonisierung von Classic- und Adaptive-Konzepten.\n</li><li><strong><code>StandardizationTemplate</code>:</strong> Definition normierter Entitäten und Blueprints (z. B. standardisierte Interface- und Parametervorlagen).\n</li><li><strong><code>FeatureModelTemplate</code>:</strong> Modellierung von 150%-Systemvarianten und Variabilitätsbindungszeitpunkten (<code>VariationPoint</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Paketbeziehungen &amp; gerichtete Abhängigkeiten (<code>&lt;&lt;use&gt;&gt;</code> / Import)</h5>\n<ul class=\"fig-list\"><li><strong><code>SystemTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> (Mapping von SWC-Ports/Signalen auf System-Signale),\n</li><li><code>EcuResourceTemplate</code> (Zuordnung von System-Knoten zu Hardware-Strukturen),\n</li><li><code>CommonStructure</code> (Verwendung gemeinsamer Basistypen).\n</li></ul>\n</li><li><strong><code>SWComponentTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>EcuResourceTemplate</code> (Definition hardwarebezogener Anforderungen von SWCs),\n</li><li><code>CommonStructure</code>.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>SystemTemplate</code> (Import des EcuExtracts zur Konfiguration von Com, CanIf, etc.),\n</li><li><code>SWComponentTemplate</code> (RTE-Konfiguration basierend auf SWC-InternalBehavior),\n</li><li><code>EcuResourceTemplate</code> (Konfiguration von MCAL-Treibern anhand realer Hardware-Ressourcen),\n</li><li><code>ECUCParameterDefTemplate</code> (Typ-Instanz-Beziehung: Werte basieren auf Moduldefinitionen),\n</li><li><code>BswModuleTemplate</code> (Zuordnung konfigurierter Instanzen zum BSW-Verhalten).\n</li></ul>\n</li><li><strong><code>BswModuleTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> (z. B. Complex Device Driver, Service-SWC-Kopplung).\n</li></ul>\n</li><li><strong><code>AdaptivePlatform</code></strong> referenziert <code>SWComponentTemplate</code>, <code>SystemTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li><strong><code>DiagnosticExtract</code></strong> referenziert <code>SWComponentTemplate</code> (Port-basierte Diagnose-Events) und <code>SystemTemplate</code> (Bus-Diagnoseprotokolle).\n</li><li><strong><code>AbstractPlatform</code></strong> referenziert <code>SWComponentTemplate</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Statik:</strong> Als rein strukturelle Metamodell-Definition existiert zur Laufzeit kein Kontrollfluss.\n</li><li><strong>Methodischer Abhängigkeitsablauf in der Toolchain (Build- &amp; Generierungs-Pipeline):</strong>\n<ol class=\"fig-list\"><li><em>Authoring:</em> Erstellung der SWC-Beschreibungen (<code>SWComponentTemplate</code>) und Hardware-Topologie (<code>EcuResourceTemplate</code>).\n</li><li><em>System Composition &amp; Extraction:</em> Definition des Gesamtsystems (<code>SystemTemplate</code>) und Ableitung des Steuergeräte-Extrakts (<code>EcuExtract</code>).\n</li><li><em>BSW-Definition &amp; Parametrisierung:</em> Abgleich von <code>EcuExtract</code>, <code>BswModuleTemplate</code> und <code>ECUCParameterDefTemplate</code> zur Befüllung der <code>ECUCDescriptionTemplate</code>.\n</li><li><em>Generierung:</em> BSW- und RTE-Code-Generatoren konsumieren die verknüpften Instanzen aus <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code> und <code>SWComponentTemplate</code> zur Erzeugung von C-Headern, Deskriptoren und Funktionsrümpfen.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Splitbarkeit («atpSplitable»):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen beachten, dass das Wurzelelement <code>&lt;AUTOSAR&gt;</code> (<code>AutosarTopLevelStructure</code>) über mehrere ARXML-Dateien fragmentiert sein kann.\n</li><li>Cross-Package-Referenzen (z. B. von einer <code>EcucModuleConfigurationValues</code> im ECU-C-File auf ein <code>SystemSignal</code> im System-File) erfolgen stets über vollqualifizierte Pfade (<code>/Package/SubPackage/ElementName</code>) via <code>Identifiable</code>-Kurznamen (<code>shortName</code>).\n</li></ul>\n</li><li><strong>Toolchain-Validierung:</strong>\n<ul class=\"fig-list\"><li>Ein unvollständiger Import abhängiger Pakete bricht die semantische Modellvalidierung. Werden beispielsweise CAN-Treiber konfiguriert (<code>ECUCDescriptionTemplate</code>), sind gültige Referenzen auf das <code>SystemTemplate</code> (Baudraten, Controller-IDs) und das <code>EcuResourceTemplate</code> (Taktfrequenzen, Register-Mappings) zwingend erforderlich.\n</li></ul>\n</li><li><strong>Auswirkung auf Treiber- und Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>BSW-Modul-Autoren (MCAL, Services) dürfen Konfigurationswerte nicht frei definieren; sie müssen über <code>ECUCParameterDefTemplate</code> strikt vorgegeben und über <code>BswModuleTemplate</code> an die Schedulable Entities des Betriebssystems (<code>OsTask</code>) gebunden werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-5d3192ff2e3d93a9", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Paketdiagramm (Package Diagram) des AUTOSAR-Metamodells auf MOF-Ebene M2 (Meta-Object Facility).\n</li><li><strong>Technischer Zweck:</strong> Definition der Modularisierung, Kapselung und statischen Abhängigkeitsstruktur der AUTOSAR-Templates für Classic Platform (CP) und Teile der Adaptive Platform (AP) im Release R23-11.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet das normative Schema (Basis für die Generierung des <code>AUTOSAR_*.xsd</code>-XML-Schemas) für alle AUTOSAR-Autorendateien (ARXML).\n</li><li>Strukturierung der Domänen in spezifische Templates (System, SWC, BSW, ECU-C, HW-Ressourcen, Diagnose) zur Trennung von Systemdesign-, Integrations- und Konfigurations-Phasen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Struktur- und Basis-Pakete</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarTopLevelStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Beherbergt die singuläre Wurzel-Metaklasse <code>AUTOSAR</code> des gesamten ARXML-Instanzmodells.\n</li><li>Aggregiert generisch alle Metaklassen über hierarchisch geschachtelte <code>ARPackage</code>-Elemente aus den Template-Paketen.\n</li></ul>\n</li><li><strong><code>CommonStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Plattformweite Basis-Metaklassen: Identifizierbarkeit (<code>Identifiable</code>, <code>Referrable</code>), primitive Datentypen, physische Einheiten/Dimensionen (<code>Unit</code>, <code>PhysicalDimension</code>), Formeln (<code>CompuMethod</code>) sowie Metadaten/Rechteverwaltung (<code>AdminData</code>).\n</li></ul>\n</li><li><strong><code>GenericStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Orthogonale Modellierungsprimitive: Typ-Instanz-Muster, generische Assoziationen, Primitive-Typ-Konzepte. Alle Top-Level-Pakete aggregieren Metaklassen aus diesem Paket (dokumentiert per Annotation).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Funktionale Template-Pakete (Classic Platform Core)</h5>\n<ul class=\"fig-list\"><li><strong><code>SWComponentTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Modellierung des Virtual Functional Bus (VFB) und der Software-Architektur: Software-Komponenten-Typen (<code>AtomicSwComponentType</code>, <code>CompositionSwComponentType</code>), Ports (<code>RPortPrototype</code>, <code>PPortPrototype</code>), Interfaces (<code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>) sowie internes Verhalten (<code>SwcInternalBehavior</code>, <code>RunnableEntity</code>).\n</li></ul>\n</li><li><strong><code>SystemTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Systemweit integrierte Beschreibung: Bus-Topologie (<code>CanCluster</code>, <code>LinCluster</code>, <code>EthernetCluster</code>), Kommunikationsmatrix (<code>Frame</code>, <code>I-PDU</code>, <code>ISignal</code>), System-Signals, ECU-Instanzen (<code>EcuInstance</code>) sowie Mappings (<code>SwcToEcuMapping</code>, <code>SystemSignalISignalMapping</code>).\n</li></ul>\n</li><li><strong><code>EcuResourceTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Hardware-Ressourcen der Steuergeräte: Mikrocontroller-Architektur, CPU-Cores, On-Chip- und Off-Chip-Peripherie, Pins und Speicherabbilder (<code>HwDescriptionEntity</code>).\n</li></ul>\n</li><li><strong><code>BswModuleTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Formale Beschreibung von BSW-Modulen und Treibern (MCAL, HAL, Service-Layer): <code>BswModuleDescription</code>, <code>BswInternalBehavior</code>, BSW-Schedulables (<code>BswSchedulableEntity</code>), Speicherzuordnungen und OS-Task-Anbindungen.\n</li></ul>\n</li><li><strong><code>ECUCParameterDefTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Metamodell für Modul-Parameter-Definitionen: Definition von Parametern, Containern und Multiplizitäten (<code>EcucModuleDef</code>, <code>EcucParamConfContainerDef</code>) für BSW-Stacks und RTE.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Konkrete ECU-Konfigurationswerte (<code>EcucValueCollection</code>, <code>EcucModuleConfigurationValues</code>), validiert gegen die zugehörigen <code>ECUCParameterDefTemplates</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Domänenübergreifende &amp; Erweiterungs-Pakete</h5>\n<ul class=\"fig-list\"><li><strong><code>AdaptivePlatform</code>:</strong> Metamodellelemente für serviceorientierte Architekturen (SOA), Adaptive Application Manifeste und Deployment.\n</li><li><strong><code>DiagnosticExtract</code>:</strong> DEXT-Diagnosespezifikation (DTCs, Diagnostic Services, Dcm/Dem-Mappings).\n</li><li><strong><code>AbstractPlatform</code>:</strong> Plattformunabhängige Abstraktionsschicht zur Harmonisierung von Classic- und Adaptive-Konzepten.\n</li><li><strong><code>StandardizationTemplate</code>:</strong> Definition normierter Entitäten und Blueprints (z. B. standardisierte Interface- und Parametervorlagen).\n</li><li><strong><code>FeatureModelTemplate</code>:</strong> Modellierung von 150%-Systemvarianten und Variabilitätsbindungszeitpunkten (<code>VariationPoint</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Paketbeziehungen &amp; gerichtete Abhängigkeiten (<code>&lt;&lt;use&gt;&gt;</code> / Import)</h5>\n<ul class=\"fig-list\"><li><strong><code>SystemTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> (Mapping von SWC-Ports/Signalen auf System-Signale),\n</li><li><code>EcuResourceTemplate</code> (Zuordnung von System-Knoten zu Hardware-Strukturen),\n</li><li><code>CommonStructure</code> (Verwendung gemeinsamer Basistypen).\n</li></ul>\n</li><li><strong><code>SWComponentTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>EcuResourceTemplate</code> (Definition hardwarebezogener Anforderungen von SWCs),\n</li><li><code>CommonStructure</code>.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>SystemTemplate</code> (Import des EcuExtracts zur Konfiguration von Com, CanIf, etc.),\n</li><li><code>SWComponentTemplate</code> (RTE-Konfiguration basierend auf SWC-InternalBehavior),\n</li><li><code>EcuResourceTemplate</code> (Konfiguration von MCAL-Treibern anhand realer Hardware-Ressourcen),\n</li><li><code>ECUCParameterDefTemplate</code> (Typ-Instanz-Beziehung: Werte basieren auf Moduldefinitionen),\n</li><li><code>BswModuleTemplate</code> (Zuordnung konfigurierter Instanzen zum BSW-Verhalten).\n</li></ul>\n</li><li><strong><code>BswModuleTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> (z. B. Complex Device Driver, Service-SWC-Kopplung).\n</li></ul>\n</li><li><strong><code>AdaptivePlatform</code></strong> referenziert <code>SWComponentTemplate</code>, <code>SystemTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li><strong><code>DiagnosticExtract</code></strong> referenziert <code>SWComponentTemplate</code> (Port-basierte Diagnose-Events) und <code>SystemTemplate</code> (Bus-Diagnoseprotokolle).\n</li><li><strong><code>AbstractPlatform</code></strong> referenziert <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Statik:</strong> Als rein strukturelle Metamodell-Definition existiert zur Laufzeit kein Kontrollfluss.\n</li><li><strong>Methodischer Abhängigkeitsablauf in der Toolchain (Build- &amp; Generierungs-Pipeline):</strong>\n<ol class=\"fig-list\"><li><em>Authoring:</em> Erstellung der SWC-Beschreibungen (<code>SWComponentTemplate</code>) und Hardware-Topologie (<code>EcuResourceTemplate</code>).\n</li><li><em>System Composition &amp; Extraction:</em> Definition des Gesamtsystems (<code>SystemTemplate</code>) und Ableitung des Steuergeräte-Extrakts (<code>EcuExtract</code>).\n</li><li><em>BSW-Definition &amp; Parametrisierung:</em> Abgleich von <code>EcuExtract</code>, <code>BswModuleTemplate</code> und <code>ECUCParameterDefTemplate</code> zur Befüllung der <code>ECUCDescriptionTemplate</code>.\n</li><li><em>Generierung:</em> BSW- und RTE-Code-Generatoren konsumieren die verknüpften Instanzen aus <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code> und <code>SWComponentTemplate</code> zur Erzeugung von C-Headern, Deskriptoren und Funktionsrümpfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Splitbarkeit («atpSplitable»):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen beachten, dass das Wurzelelement <code>&lt;AUTOSAR&gt;</code> (<code>AutosarTopLevelStructure</code>) über mehrere ARXML-Dateien fragmentiert sein kann.\n</li><li>Cross-Package-Referenzen (z. B. von einer <code>EcucModuleConfigurationValues</code> im ECU-C-File auf ein <code>SystemSignal</code> im System-File) erfolgen stets über vollqualifizierte Pfade (<code>/Package/SubPackage/ElementName</code>) via <code>Identifiable</code>-Kurznamen (<code>shortName</code>).\n</li></ul>\n</li><li><strong>Toolchain-Validierung:</strong>\n<ul class=\"fig-list\"><li>Ein unvollständiger Import abhängiger Pakete bricht die semantische Modellvalidierung. Werden beispielsweise CAN-Treiber konfiguriert (<code>ECUCDescriptionTemplate</code>), sind gültige Referenzen auf das <code>SystemTemplate</code> (Baudraten, Controller-IDs) und das <code>EcuResourceTemplate</code> (Taktfrequenzen, Register-Mappings) zwingend erforderlich.\n</li></ul>\n</li><li><strong>Auswirkung auf Treiber- und Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>BSW-Modul-Autoren (MCAL, Services) dürfen Konfigurationswerte nicht frei definieren; sie müssen über <code>ECUCParameterDefTemplate</code> strikt vorgegeben und über <code>BswModuleTemplate</code> an die Schedulable Entities des Betriebssystems (<code>OsTask</code>) gebunden werden.\n</li></ul>\n</li></ul>"}, {"id": "FIG-7e94c6d6aa9521e6", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Paketdiagramm (Package Diagram) des AUTOSAR-Metamodells auf MOF-Ebene M2 (Meta-Object Facility).\n</li><li><strong>Technischer Zweck:</strong> Definition der Modularisierung, Kapselung und statischen Abhängigkeitsstruktur der AUTOSAR-Templates für Classic Platform (CP) und Teile der Adaptive Platform (AP) im Release R23-11.\n</li><li><strong>Funktionale Einordnung:</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet das normative Schema (Basis für die Generierung des <code>AUTOSAR_*.xsd</code>-XML-Schemas) für alle AUTOSAR-Autorendateien (ARXML).\n</li><li>Strukturierung der Domänen in spezifische Templates (System, SWC, BSW, ECU-C, HW-Ressourcen, Diagnose) zur Trennung von Systemdesign-, Integrations- und Konfigurations-Phasen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Zentrale Struktur- und Basis-Pakete</h5>\n<ul class=\"fig-list\"><li><strong><code>AutosarTopLevelStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Beherbergt die singuläre Wurzel-Metaklasse <code>AUTOSAR</code> des gesamten ARXML-Instanzmodells.\n</li><li>Aggregiert generisch alle Metaklassen über hierarchisch geschachtelte <code>ARPackage</code>-Elemente aus den Template-Paketen.\n</li></ul>\n</li><li><strong><code>CommonStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Plattformweite Basis-Metaklassen: Identifizierbarkeit (<code>Identifiable</code>, <code>Referrable</code>), primitive Datentypen, physische Einheiten/Dimensionen (<code>Unit</code>, <code>PhysicalDimension</code>), Formeln (<code>CompuMethod</code>) sowie Metadaten/Rechteverwaltung (<code>AdminData</code>).\n</li></ul>\n</li><li><strong><code>GenericStructure</code>:</strong>\n<ul class=\"fig-list\"><li>Orthogonale Modellierungsprimitive: Typ-Instanz-Muster, generische Assoziationen, Primitive-Typ-Konzepte. Alle Top-Level-Pakete aggregieren Metaklassen aus diesem Paket (dokumentiert per Annotation).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Funktionale Template-Pakete (Classic Platform Core)</h5>\n<ul class=\"fig-list\"><li><strong><code>SWComponentTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Modellierung des Virtual Functional Bus (VFB) und der Software-Architektur: Software-Komponenten-Typen (<code>AtomicSwComponentType</code>, <code>CompositionSwComponentType</code>), Ports (<code>RPortPrototype</code>, <code>PPortPrototype</code>), Interfaces (<code>SenderReceiverInterface</code>, <code>ClientServerInterface</code>) sowie internes Verhalten (<code>SwcInternalBehavior</code>, <code>RunnableEntity</code>).\n</li></ul>\n</li><li><strong><code>SystemTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Systemweit integrierte Beschreibung: Bus-Topologie (<code>CanCluster</code>, <code>LinCluster</code>, <code>EthernetCluster</code>), Kommunikationsmatrix (<code>Frame</code>, <code>I-PDU</code>, <code>ISignal</code>), System-Signals, ECU-Instanzen (<code>EcuInstance</code>) sowie Mappings (<code>SwcToEcuMapping</code>, <code>SystemSignalISignalMapping</code>).\n</li></ul>\n</li><li><strong><code>EcuResourceTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Hardware-Ressourcen der Steuergeräte: Mikrocontroller-Architektur, CPU-Cores, On-Chip- und Off-Chip-Peripherie, Pins und Speicherabbilder (<code>HwDescriptionEntity</code>).\n</li></ul>\n</li><li><strong><code>BswModuleTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Formale Beschreibung von BSW-Modulen und Treibern (MCAL, HAL, Service-Layer): <code>BswModuleDescription</code>, <code>BswInternalBehavior</code>, BSW-Schedulables (<code>BswSchedulableEntity</code>), Speicherzuordnungen und OS-Task-Anbindungen.\n</li></ul>\n</li><li><strong><code>ECUCParameterDefTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Metamodell für Modul-Parameter-Definitionen: Definition von Parametern, Containern und Multiplizitäten (<code>EcucModuleDef</code>, <code>EcucParamConfContainerDef</code>) für BSW-Stacks und RTE.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate</code>:</strong>\n<ul class=\"fig-list\"><li>Konkrete ECU-Konfigurationswerte (<code>EcucValueCollection</code>, <code>EcucModuleConfigurationValues</code>), validiert gegen die zugehörigen <code>ECUCParameterDefTemplates</code>.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Domänenübergreifende &amp; Erweiterungs-Pakete</h5>\n<ul class=\"fig-list\"><li><strong><code>AdaptivePlatform</code>:</strong> Metamodellelemente für serviceorientierte Architekturen (SOA), Adaptive Application Manifeste und Deployment.\n</li><li><strong><code>DiagnosticExtract</code>:</strong> DEXT-Diagnosespezifikation (DTCs, Diagnostic Services, Dcm/Dem-Mappings).\n</li><li><strong><code>AbstractPlatform</code>:</strong> Plattformunabhängige Abstraktionsschicht zur Harmonisierung von Classic- und Adaptive-Konzepten.\n</li><li><strong><code>StandardizationTemplate</code>:</strong> Definition normierter Entitäten und Blueprints (z. B. standardisierte Interface- und Parametervorlagen).\n</li><li><strong><code>FeatureModelTemplate</code>:</strong> Modellierung von 150%-Systemvarianten und Variabilitätsbindungszeitpunkten (<code>VariationPoint</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Paketbeziehungen &amp; gerichtete Abhängigkeiten (<code>&lt;&lt;use&gt;&gt;</code> / Import)</h5>\n<ul class=\"fig-list\"><li><strong><code>SystemTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> (Mapping von SWC-Ports/Signalen auf System-Signale),\n</li><li><code>EcuResourceTemplate</code> (Zuordnung von System-Knoten zu Hardware-Strukturen),\n</li><li><code>CommonStructure</code> (Verwendung gemeinsamer Basistypen).\n</li></ul>\n</li><li><strong><code>SWComponentTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>EcuResourceTemplate</code> (Definition hardwarebezogener Anforderungen von SWCs),\n</li><li><code>CommonStructure</code>.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>SystemTemplate</code> (Import des EcuExtracts zur Konfiguration von Com, CanIf, etc.),\n</li><li><code>SWComponentTemplate</code> (RTE-Konfiguration basierend auf SWC-InternalBehavior),\n</li><li><code>EcuResourceTemplate</code> (Konfiguration von MCAL-Treibern anhand realer Hardware-Ressourcen),\n</li><li><code>ECUCParameterDefTemplate</code> (Typ-Instanz-Beziehung: Werte basieren auf Moduldefinitionen),\n</li><li><code>BswModuleTemplate</code> (Zuordnung konfigurierter Instanzen zum BSW-Verhalten).\n</li></ul>\n</li><li><strong><code>BswModuleTemplate</code></strong> referenziert:\n<ul class=\"fig-list\"><li><code>CommonStructure</code>, <code>EcuResourceTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>SWComponentTemplate</code> (z. B. Complex Device Driver, Service-SWC-Kopplung).\n</li></ul>\n</li><li><strong><code>AdaptivePlatform</code></strong> referenziert <code>SWComponentTemplate</code>, <code>SystemTemplate</code> und <code>DiagnosticExtract</code>.\n</li><li><strong><code>DiagnosticExtract</code></strong> referenziert <code>SWComponentTemplate</code> (Port-basierte Diagnose-Events) und <code>SystemTemplate</code> (Bus-Diagnoseprotokolle).\n</li><li><strong><code>AbstractPlatform</code></strong> referenziert <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Statik:</strong> Als rein strukturelle Metamodell-Definition existiert zur Laufzeit kein Kontrollfluss.\n</li><li><strong>Methodischer Abhängigkeitsablauf in der Toolchain (Build- &amp; Generierungs-Pipeline):</strong>\n<ol class=\"fig-list\"><li><em>Authoring:</em> Erstellung der SWC-Beschreibungen (<code>SWComponentTemplate</code>) und Hardware-Topologie (<code>EcuResourceTemplate</code>).\n</li><li><em>System Composition &amp; Extraction:</em> Definition des Gesamtsystems (<code>SystemTemplate</code>) und Ableitung des Steuergeräte-Extrakts (<code>EcuExtract</code>).\n</li><li><em>BSW-Definition &amp; Parametrisierung:</em> Abgleich von <code>EcuExtract</code>, <code>BswModuleTemplate</code> und <code>ECUCParameterDefTemplate</code> zur Befüllung der <code>ECUCDescriptionTemplate</code>.\n</li><li><em>Generierung:</em> BSW- und RTE-Code-Generatoren konsumieren die verknüpften Instanzen aus <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code> und <code>SWComponentTemplate</code> zur Erzeugung von C-Headern, Deskriptoren und Funktionsrümpfen.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung &amp; Splitbarkeit («atpSplitable»):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen beachten, dass das Wurzelelement <code>&lt;AUTOSAR&gt;</code> (<code>AutosarTopLevelStructure</code>) über mehrere ARXML-Dateien fragmentiert sein kann.\n</li><li>Cross-Package-Referenzen (z. B. von einer <code>EcucModuleConfigurationValues</code> im ECU-C-File auf ein <code>SystemSignal</code> im System-File) erfolgen stets über vollqualifizierte Pfade (<code>/Package/SubPackage/ElementName</code>) via <code>Identifiable</code>-Kurznamen (<code>shortName</code>).\n</li></ul>\n</li><li><strong>Toolchain-Validierung:</strong>\n<ul class=\"fig-list\"><li>Ein unvollständiger Import abhängiger Pakete bricht die semantische Modellvalidierung. Werden beispielsweise CAN-Treiber konfiguriert (<code>ECUCDescriptionTemplate</code>), sind gültige Referenzen auf das <code>SystemTemplate</code> (Baudraten, Controller-IDs) und das <code>EcuResourceTemplate</code> (Taktfrequenzen, Register-Mappings) zwingend erforderlich.\n</li></ul>\n</li><li><strong>Auswirkung auf Treiber- und Stack-Entwickler:</strong>\n<ul class=\"fig-list\"><li>BSW-Modul-Autoren (MCAL, Services) dürfen Konfigurationswerte nicht frei definieren; sie müssen über <code>ECUCParameterDefTemplate</code> strikt vorgegeben und über <code>BswModuleTemplate</code> an die Schedulable Entities des Betriebssystems (<code>OsTask</code>) gebunden werden.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-6266e54630fa8845", "to": "FIG-5d3192ff2e3d93a9", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5d3192ff2e3d93a9", "to": "FIG-7e94c6d6aa9521e6", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
